// A short welcome for each newly created book, with a replay in Book options.
(()=>{
 const $=s=>document.querySelector(s);
 const steps=[
  {title:'Make this book yours.',text:'Your title and cover are just the beginning. Choose blank or lined pages, change their color, and make space for your kind of day.',tools:['Book → Cover & title','Book → Paper & page color'],preview:'paper',caption:'A little room to be yourself.'},
  {title:'Say it. Or type it.',text:'Start the microphone and choose a voice option, or use Type to write a request. Full pages continue onto the next page automatically.',tools:['Microphone','Type','Undo'],preview:'voice',caption:'Try: “Diary, add note: remember this.”'},
  {title:'Keep more than words.',text:'Open Add for sticky notes, photos, video, paper pieces, and audio uploads. Click a note to write on it; move it by its grip. Recordings get a play button.',tools:['Add → Sticky note','Add → Photo / video','Add → Voice recording'],preview:'memories',caption:'Your day, with all the little extras.'},
  {title:'Find your way back.',text:'Contents takes you to a page in this book. My Books holds your account library. Ideas for Later keeps thoughts that have not found a book yet. Wait for “Saved to account” before leaving.',tools:['Contents','My Books','Ideas for Later'],preview:'shelf',caption:'Your books stay with your signed-in account.'}
 ];
 const dialog=document.createElement('dialog');dialog.id='book-tutorial';dialog.setAttribute('aria-labelledby','tutorial-title');dialog.innerHTML='<button class="dialog-close" id="tutorial-close" aria-label="Skip quick tour">×</button><div class="eyebrow">A LITTLE HELLO TO YOUR NEW BOOK</div><p id="tutorial-book-name"></p><div id="tutorial-preview" aria-hidden="true"></div><div id="tutorial-progress" aria-label="Tour steps"></div><p id="tutorial-step-count" class="tutorial-step-count"></p><div aria-live="polite"><h2 id="tutorial-title"></h2><p id="tutorial-description"></p><div id="tutorial-tools"></div><p id="tutorial-caption"></p></div><div class="tutorial-footer"><button id="tutorial-skip">Skip tour</button><div><button id="tutorial-back">Back</button><button class="primary" id="tutorial-next">Next</button></div></div><label class="tutorial-preference"><input id="tutorial-auto" type="checkbox" checked>Show a quick tour with new books</label>';document.body.append(dialog);
 let index=0,bookId=null,returnFocus=null;
 const previews={paper:'<div class="tour-mini-cover">MY<br>LITTLE<br>STORIES.<span>✳</span></div><div class="tour-mini-page"><i></i><i></i><i></i></div>',voice:'<div class="tour-mic-symbol">●</div><div class="tour-sound-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="tour-words">Dear diary, today…</div>',memories:'<div class="tour-mini-note">remember<br>this.</div><div class="tour-photo-symbol">a moment<br>worth keeping</div><div class="tour-audio-symbol">▶ &nbsp; A little voice note</div>',shelf:'<div class="tour-shelf-book">EVERYDAY</div><div class="tour-shelf-book">SMALL JOYS</div><div class="tour-shelf-book">NEXT CHAPTER</div>'};
 function autoEnabled(){try{return localStorage.getItem('wd-tour-auto')!=='false'}catch{return true}}
 function render(){const step=steps[index];$('#tutorial-title').textContent=step.title;$('#tutorial-description').textContent=step.text;$('#tutorial-caption').textContent=step.caption;$('#tutorial-step-count').textContent='QUICK TOUR · '+(index+1)+' OF '+steps.length;$('#tutorial-preview').className='tutorial-preview preview-'+step.preview;$('#tutorial-preview').innerHTML=previews[step.preview];$('#tutorial-back').hidden=index===0;$('#tutorial-next').textContent=index===steps.length-1?'Start my story ↗':'Next →';const tools=$('#tutorial-tools');tools.replaceChildren();for(const label of step.tools){const item=document.createElement('span');item.textContent=label;tools.append(item)}const progress=$('#tutorial-progress');progress.replaceChildren();steps.forEach((_,number)=>{const dot=document.createElement('button');dot.setAttribute('aria-label','Tour step '+(number+1));dot.setAttribute('aria-current',number===index?'step':'false');dot.onclick=()=>{index=number;render()};progress.append(dot)})}
 function close(){dialog.close();if(bookId===activeBookId)returnFocus?.focus?.()}
 function show({automatic=false,id=activeBookId}={}){const book=books.find(b=>b.id===id);if(!book||automatic&&(book.isSample||!autoEnabled()))return false;if(dialog.open)dialog.close();window.voiceSession?.stop('Microphone paused for the quick tour. Start it again when you are ready.');index=0;bookId=id;returnFocus=document.activeElement;$('#tutorial-book-name').textContent=book.title;$('#tutorial-auto').checked=autoEnabled();render();dialog.showModal();return true}
 $('#tutorial-next').onclick=()=>{if(index===steps.length-1)close();else{index++;render()}};$('#tutorial-back').onclick=()=>{index=Math.max(0,index-1);render()};$('#tutorial-skip').onclick=close;$('#tutorial-close').onclick=close;$('#tutorial-auto').onchange=event=>{try{localStorage.setItem('wd-tour-auto',String(event.target.checked))}catch{toast('The tour preference could not be saved in this browser.')}};
 dialog.addEventListener('keydown',event=>{if(event.key==='ArrowRight'&&index<steps.length-1){event.preventDefault();index++;render()}if(event.key==='ArrowLeft'&&index>0){event.preventDefault();index--;render()}});
 window.addEventListener('diary-book-created',event=>show({automatic:true,id:event.detail.bookId}));document.addEventListener('diary-auth-change',()=>dialog.close());
 const replay=document.createElement('button');replay.id='replay-book-tutorial';replay.textContent='Quick tour';replay.dataset.bookAction='true';replay.onclick=()=>show();$('.book-options-list').append(replay);
 window.diaryTutorial={show,close,autoEnabled};
})();
